import { formatPrice } from "./price.ts";

/** One line of the cart: the item and its price. */
export function cartLine(item: string, cents: number): string {
  return `${item}: ${formatPrice(cents)}`;
}

files.src/date.ts:
/** A date as the shop prints it: 2026-10-21. */
export function formatDate(date: Date): string {
  return date.toISOString().slice(0, 10);
}

